!function(r){function p(p){for(var a,e,o=p[0],m=p[1],c=p[2],y=0,g=[];y<o.length;y++)e=o[y],Object.prototype.hasOwnProperty.call(i,e)&&i[e]&&g.push(i[e][0]),i[e]=0;for(a in m)Object.prototype.hasOwnProperty.call(m,a)&&(r[a]=m[a]);for(u&&u(p);g.length;)g.shift()();return t.push.apply(t,c||[]),n()}function n(){for(var r,p=0;p<t.length;p++){for(var n,e=t[p],o=!0,m=1;m<e.length;m++)n=e[m],0!==i[n]&&(o=!1);o&&(t.splice(p--,1),r=a(a.s=e[0]))}return r}function a(p){if(e[p])return e[p].exports;var n=e[p]={i:p,l:!1,exports:{}};return r[p].call(n.exports,n,n.exports,a),n.l=!0,n.exports}var e={},i={8:0},t=[];a.m=r,a.c=e,a.d=function(r,p,n){a.o(r,p)||Object.defineProperty(r,p,{enumerable:!0,get:n})},a.r=function(r){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(r,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(r,"__esModule",{value:!0})},a.t=function(r,p){if(1&p&&(r=a(r)),8&p)return r;if(4&p&&"object"==typeof r&&r&&r.__esModule)return r;var n=Object.create(null);if(a.r(n),Object.defineProperty(n,"default",{enumerable:!0,value:r}),2&p&&"string"!=typeof r)for(var e in r)a.d(n,e,function(p){return r[p]}.bind(null,e));return n},a.n=function(r){var p=r&&r.__esModule?function(){return r.default}:function(){return r};return a.d(p,"a",p),p},a.o=function(r,p){return Object.prototype.hasOwnProperty.call(r,p)},a.p="";var o=window.webpackJsonp=window.webpackJsonp||[],m=o.push.bind(o);o.push=p,o=o.slice();for(var c=0;c<o.length;c++)p(o[c]);var u=m;t.push([64,0]),n()}({64:function(r,p,n){"use strict";n.r(p);var a=n(0);Object(a.a)("ru","army",n(65),n(1))},65:function(r){r.exports=JSON.parse('{"category":[{"name":"苏联","link":"ru_shortcut"},{"name":"陆战武器","link":"ru_army"},{"name":"火炮","link":"ru_army#ru_army_cannon"}],"model":"苏军重炮","description":"<h6>综述：</h6><p>二战中，苏军装备的重型火炮有1931式203毫米榴弹炮、1939式230毫米加农炮、1939式280毫米榴弹炮和1939式305毫米榴弹炮等几种。</p><p>1931式203毫米榴弹炮（B-4型）虽是二战前生产的重炮，但经过多次改进，成为二战中苏军极具攻坚威力的重炮，该型炮一共生产了870多门，在苏军重炮部队中服役到二战结束，德军称之为“斯大林之锤”，可见对其火力的畏惧。</p><p>1939式210毫米加农炮（BR-17型）是在1939年装备苏军，该炮采用了和B-4同样的炮架和履带，亦具有强大的火力，但在二战初期就被德军缴获了70多门。</p><p>1939式280毫米榴弹炮（有资料称为重型迫击炮）也是1939年加入苏军的其中一种威力巨大的重炮，但因其生产数量不多，在二战中的战绩远不如B-4型203毫米重炮。</p><p>1939式305毫米榴弹炮（BR-18型）是苏军在二战中最具镇慑力的巨炮，其炮弹重达330公斤，能在1000米距离以60度角穿透2米多厚的混凝土工事，但由于其十分笨重，进入战斗状态需时很长，因此只在1944年列宁格勒反击战中便用过。</p>","part1title":"系列型号","part1description":"","part1content":[{"image":"{{image}}imgs/ru/army/ru_army_cannonHeavy_10.jpg{{text}}1931式203mm榴弹炮四视图{{image}}imgs/ru/army/ru_army_cannonHeavy_11.jpg","description":"<h6>1931式（B-4型）203mm榴弹炮</h6><p></p><p>基本技术数据：</p><p>火炮口径：203毫米；</p><p>炮管长度：5087毫米；炮管重：5.2吨；</p><p>火炮全重：17.7吨；</p><p>高低射角：-2°～+60°，水平射界：左右30°；</p><p>炮口初速：607米/秒；最大射速：1～3发/分钟；</p><p>最大射程：17.5公里；</p><p>牵引时最大行驶速度：15千米/小时；</p><p>炮组成员：15人。</p>","caption":""},{"image":"imgs/ru/army/ru_army_cannonHeavy_12.jpg","description":"<h6>1939式（BR-17型）210mm加农炮</h6><p></p><p>基本技术数据：</p><p>火炮口径：210毫米；</p><p>炮管长度：10.1米；全炮重量：4.32吨；</p><p>炮口初速：800米/秒；</p><p>最大射速：20发/小时；</p><p>最大射程：29.4公里；</p><p>牵引时最大行驶速度：25～30千米/小时。</p>","caption":""},{"image":"imgs/ru/army/ru_army_cannonHeavy_13.jpg","description":"<h6>1939式280mm榴弹炮</h6><p></p><p>基本技术数据：</p><p>火炮口径：280毫米；</p><p>炮管长度：4米；全炮重量：18.4吨（能分拆为三部分运输）；</p><p>炮口初速：356米/秒；</p><p>高低射角：0°～+60°，水平射界：左右8°；</p><p>最大射速：15发/小时；</p><p>最大射程：10.65公里；</p><p>牵引时最大行驶速度：25～30千米/小时。</p>","caption":""},{"image":"imgs/ru/army/ru_army_cannonHeavy_14.jpg","description":"<h6>1939式（BR-18型）305mm榴弹炮</h6><p></p><p>基本技术数据：</p><p>火炮口径：305毫米；</p><p>炮管长度：4米；战斗重量：45.7吨，运输重量：54吨（能分拆为三部分运输）；</p><p>炮口初速：530米/秒；</p><p>高低射角：0°～+60°，水平射界：左右8°；</p><p>最大射速：20发/小时；</p><p>最大射程：16.5公里；</p><p>牵引时最大行驶速度：25～30千米/小时。</p>","caption":""}],"part2title":"战场上的苏军重炮","part2description":"","part2content":[{"image":"imgs/ru/army/ru_army_cannonHeavy_20.jpg","description":"二战战场上苏军一门隐蔽在树林中的1931式203毫米榴弹炮。该炮生产后，只装备苏军最高统帅部直接控制的后备炮兵部队和集团军直属炮兵营。每营装备12门，可进行高射角射击或直瞄射击，主要负责摧毁距战斗前沿较远的坚固混凝土工事。","caption":""},{"image":"imgs/ru/army/ru_army_cannonHeavy_21.jpg","description":"二战东线苏联战场，冬季雪地上，苏军将一门1931式203毫米榴弹炮运到阵地。","caption":""},{"image":"imgs/ru/army/ru_army_cannonHeavy_22.jpg","description":"二战期间，在苏联布尔什维克工厂生产中的1931式203毫米榴弹炮。该炮的研制由来自彼尔姆兵工厂的弗·费·伦杰尔工程师负责，同时负责研制火炮身管与炮瞄器材，炮架则交给布尔什维克工厂研制，整个计划原定于1927年5月完成，但由于存在诸多缺陷，因此到了1931年6月，该炮才开始装备苏军，后来又在服役过程中不断改进。","caption":""},{"image":"imgs/ru/army/ru_army_cannonHeavy_23.jpg","description":"二战东线苏联战场，苏军一门1931式203毫米榴弹炮已处于射击准备状态。弹药小车已经装好一枚炮弹，炮兵正操纵起重机将其吊起准备上膛。该炮备有混凝土穿透弹和特殊的尾翼稳定炮弹，最大能贯穿4米厚的混凝土工事。","caption":""},{"image":"imgs/ru/army/ru_army_cannonHeavy_24.jpg","description":"二战东线苏联战场，苏军正将一门1931式203毫米榴弹炮运往前线阵地。该炮安装了履带式自行炮架，炮架尾部装有辅助轮用于牵引，一般采用拖拉机牵引，从而具备较好的机动能力，需要长途运输时，可将其拆为炮架和炮管两部分搭载在运输工具上。","caption":""},{"image":"imgs/ru/army/ru_army_cannonHeavy_25.jpg","description":"1945年春天，二战东线战场波罗的海沿海，隶属苏联波罗的海第2方面军的一门1931式203毫米榴弹炮的炮班战士正在作战斗前准备。","caption":""},{"image":"imgs/ru/army/ru_army_cannonHeavy_26.jpg","description":"1944年5月，二战东线苏联战场克里米亚萨逢山附近，苏军一个1931式203毫米榴弹炮阵地，炮兵正在检测瞄准装置，作好战斗准备。1931式203毫米榴弹炮首战在1939年底的苏芬战场，它在摧毁芬兰军队永久火力点的战斗中显示了巨大威力。后在苏德战场上的哈尔科夫、柴科斯基、柯尼斯堡、但泽以及进攻柏林的战斗中，苏军一直都装备着该炮。1944年6月5日列宁格勒战场，苏军两个203毫米榴弹炮连摧毁了深藏地下达3个楼层用钢筋混凝土加固的一个重型碉堡。","caption":""},{"image":"imgs/ru/army/ru_army_cannonHeavy_27.jpg","description":"1944年冬季，二战东线苏联战场，苏军一门正在战斗中的1931式203毫米榴弹炮，操纵这门重型火炮需要多名有经验的炮兵通力合作，才能发挥其战斗威力。","caption":""},{"image":"imgs/ru/army/ru_army_cannonHeavy_28.jpg","description":"二战东线苏联战场，苏军炮兵正在将炮弹推入一门1931式203毫米榴弹炮的炮膛，这门重炮的炮弹重达98.5公斤，爆炸威力极大。该炮采用弹丸和药包分离的方式，炮架左侧装有一小型起重机用于调运弹药，炮弹发射速率一般为1发/分钟，只有十分熟练且密切协作的炮兵才有可能达到3发/分钟。","caption":""},{"image":"imgs/ru/army/ru_army_cannonHeavy_29.jpg","description":"1944年，二战东线苏联战场，苏军一门1931式203毫米榴弹炮的炮兵正在炮长的指挥下将炮膛抬高，火炮右边的瞄准手正在大声报出调整角度，侧方一名站立的军官认真观察着火炮的炮管是否调整至射击角度。","caption":""},{"image":"imgs/ru/army/ru_army_cannonHeavy_30.jpg","description":"1945年春季，二战东线战场，苏军攻入德国首都柏林，苏联白俄罗斯第1方面军将一门1931式203毫米榴弹炮推进至柏林街道，准备给德军最后一击。注意：图中三名炮兵正合力将弹药推上膛。1945年4月30日，苏军第150师和171师已攻到柏林国会大厦，为了攻入这个第三帝国的最后堡垒，苏军集中了89门包括203毫米榴弹炮、火箭炮和152自行火炮，对国会大厦进行了猛烈轰击，将国会大厦坚厚的外墙轰出一个个大洞，下午14点25分，苏军三个步兵营冲入国会大厦，经过残酷的近战，18时苏军战士终于将红旗插上了国会大厦圆顶上。同日希特勒自杀，纳粹德国灭亡。","caption":""},{"image":"imgs/ru/army/ru_army_cannonHeavy_31.jpg","description":"绘画：苏军一门1931式203毫米榴弹炮。图中火炮旁边只有2名炮兵，对一个标配15人的炮班也许是太少了。在二战期间，苏军对203毫米重炮的防卫是十分重视的，一个203毫米重炮连一般会配备1个步兵营、1个76毫米炮兵营、5辆坦克以及18挺轻重机枪作护卫。","caption":""}]}')}});